source='''def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    row_counts = {}
    col_counts = {}
    for r, c in points:
        row_counts[r] = row_counts.get(r, 0) + 1
        col_counts[c] = col_counts.get(c, 0) + 1
    # The aligned pair defines the central bar; other points connect to it.
    if max(row_counts.values(), default=0) >= max(col_counts.values(), default=0):
        axis = max(row_counts, key=row_counts.get)
        anchors = [c for r, c in points if r == axis]
        lo, hi = min(anchors), max(anchors)
        for c in range(lo, hi + 1):
            if out[axis][c] == 0:
                out[axis][c] = 3
        for r, c in points:
            if r != axis:
                for rr in range(min(r, axis), max(r, axis) + 1):
                    if out[rr][c] == 0:
                        out[rr][c] = 3
    else:
        axis = max(col_counts, key=col_counts.get)
        anchors = [r for r, c in points if c == axis]
        lo, hi = min(anchors), max(anchors)
        for r in range(lo, hi + 1):
            if out[r][axis] == 0:
                out[r][axis] = 3
        for r, c in points:
            if c != axis:
                for cc in range(min(c, axis), max(c, axis) + 1):
                    if out[r][cc] == 0:
                        out[r][cc] = 3
    return out
'''
